import type Database from 'better-sqlite3'
import { removeSavedEntry } from '../ai/knowledge.js'

/**
 * Remove a simulated interview and all knowledge notes generated by it.
 *
 * The interview turns are removed by the session's foreign-key cascade. Their
 * answer notes use the turn id as `reference_id`, while the initial JD note
 * uses the session id, so both references must be removed explicitly before
 * deleting the session. Keeping this operation in a small database service
 * makes it testable without booting Electron.
 */
export function deleteInterviewSession(db: Database.Database, id: string): string {
  const session = db.prepare('SELECT id, notebook_id FROM interview_session WHERE id = ?').get(id) as { id: string; notebook_id: string } | undefined
  if (!session) throw new Error('模拟面试不存在')
  const turnIds = (db.prepare('SELECT id FROM interview_turn WHERE session_id = ?').all(id) as Array<{ id: string }>).map(turn => turn.id)
  db.transaction(() => {
    // The session's JD supplement and each graded-turn supplement are all
    // generated by this interview and can safely be removed with it.
    db.prepare('DELETE FROM supplement WHERE reference_id = ?').run(id)
    if (turnIds.length) {
      const placeholders = turnIds.map(() => '?').join(', ')
      db.prepare(`DELETE FROM supplement WHERE reference_id IN (${placeholders})`).run(...turnIds)
    }
    db.prepare('DELETE FROM interview_session WHERE id = ?').run(id)
    db.prepare("UPDATE notebook SET updated_at = datetime('now') WHERE id = ?").run(session.notebook_id)
  })()
  // The database transaction above removes the searchable records. The
  // transcript export is a separate deterministic file and should disappear
  // with the session as well; a failed filesystem cleanup must not roll back a
  // successful database deletion.
  removeSavedEntry(db, session.notebook_id, id)
  return session.notebook_id
}
